  ('mm-61-explorer-exoframe', 'Feet (2)', 90, 'each', 7),
  ('mm-61-explorer-exoframe', 'Spotlights (4)', 2, 'each; difficult target: called shot only, -3 to strike', 8),
  ('mm-61-explorer-exoframe', 'Main Body', 200, 'destroying it turns the exoskeleton into scrap', 9);

INSERT OR IGNORE INTO vehicle_weapons (vehicle_slug, ordinal, name, damage, is_mega_damage, range, rate_of_fire, payload, bonus, note)
VALUES
  ('tek-12-yy110-bushbike', 1, 'AR-36 Machinegun or Laser', 'Machinegun: 1D6 M.D. per 10 round burst (only fires bursts). Laser: 2D6 M.D.', 1, '1,600 feet (487 m) for both the machinegun and the optional laser', 'Equal to the number of combined hand to hand attacks of the pilot (usually 3-5)', 'Machinegun: 800 rounds in a small ammo drum (80 shots). Laser: unlimited with nuclear power supply.', NULL, 'Primary purpose defense, secondary assault. Fixed-forward mounted machinegun; nuclear powered bikes usually have a laser instead.'),
  ('tek-12-yy110-bushbike', 2, 'Mini-Missile Launchers', 'Varies with missile type, but typically Armor Piercing (1D4x10 M.D.)', 1, 'One mile (1.6 km)', '1, 2 or 4 missiles in a volley', 'Four total, two per each launcher', NULL, 'Primary purpose anti-vehicle, secondary assault. A pair of launchers (2 missiles each) alongside the rear wheel, one per side, pointing out and forward; launched by cyber-link or the press of a button.'),
  ('tek-12-yy110-bushbike', 3, 'Optional Mini-Missile Blunderbuss Launcher', 'Varies with missile type, but typically Armor Piercing (1D4x10 M.D.)', 1, 'One mile (1.6 km)', '1, 2 or 4 missiles in a volley', 'Twelve total', NULL, 'Optional. Primary purpose anti-vehicle, secondary assault. A multi-shot launcher called the Blunderbuss that replaces the rear storage compartment; basic gear is then strapped on or carried in saddlebags. Costs an extra 40,000 credits.'),
  ('tek-20-yy210-borgbike', 1, 'AR-44 Rail Gun', '1D6x10+10 M.D. per 40 round burst; only fires bursts', 1, '5,000 feet (1522 m)', NULL, 'Belt-fed ammo drum with 2,400 rounds (60 shots)', NULL, 'Primary purpose anti-personnel, secondary anti-vehicle. Sits behind the rider''s shoulder on a swivel bracket and is pulled down to fire; can also be aimed and fired by Cyber-link. Weight 155 pounds (69.75 kg). No rate of fire is printed.'),
  ('tek-20-yy210-borgbike', 2, 'Short-Range Laser', '3D6 M.D. per shot', 1, '1200 feet (printed ''610 km''; km should read m, and 1200 feet is about 366 m while 610 m is 2,000 feet)', 'Equal to the pilot''s attacks per round, +1 if only the laser is used the entire melee round', 'Effectively unlimited if nuclear; otherwise a generator pack with a 120 shot payload', NULL, 'Primary purpose anti-personnel, secondary defense. High-powered laser in a fixed forward mount, fired by a button or Cyber-Link.'),
  ('tek-20-yy210-borgbike', 3, 'Mini-Missile Blunderbuss Launcher', 'Varies with missile type, but typically Armor Piercing (1D4x10 M.D.)', 1, 'One mile (1.6 km)', '1, 2 or 4 missiles in a volley', 'Eighteen total', NULL, 'Primary purpose anti-vehicle, secondary assault. Multi-shot launcher behind the driver at the rear, known as the Big Blunderbuss.'),
  ('tek-20-yy210-borgbike', 4, 'Vibro-Lance', 'Slash attack: 2D6 M.D. +1D6 M.D. per 20 mph (31 km) of speed. Impale attack: 1D4x10 +1D6 M.D. per 20 mph (31 km) of speed.', 1, 'Extends to 7 feet (2.1 m) in front of the bike', NULL, NULL, '-3 to strike on the all-out charge impale', 'Primary purpose anti-personnel, secondary intimidation (H.F. 12). Retractable, pointed, quadruple edged blade beside the front wheel. An impale that does not destroy the victim''s armor still throws him 2D4x10 yards/meters, costs three melee attacks and does 4D6 S.D.C./Hit Point damage (none to cyborgs, robots, creatures of magic, supernatural or M.D.C. beings). All-out charge: counts as three melee attacks; the driver picks one target to impale at -3 to strike (1D20 as normal); in any case 1D6 M.D. to 1D4 characters struck or sent flying (they lose three melee attacks), slash damage to 1D4 characters, those who dodge clear lose two melee actions, those who stand in the direct line are automatically slashed, and those nearby are knocked down for 1D6 M.D. The charge does 2D6 M.D. to the ''Borgbike and 1D6 M.D. to the Vibro-Lance.'),
  ('landflier', 1, 'Dual Forward Lasers (2)', '2D6 M.D. per single shot, or 4D6 per dual blast', 1, '1,200 feet (printed ''610 m''; 1,200 feet is about 366 m and 610 m is 2,000 feet)', 'Equal to the number of hand to hand attacks of the pilot (usually 4-6)', 'E-Pack with 100 shots if a fuel engine, or unlimited if nuclear powered', NULL, 'Primary purpose defense, secondary assault. A pair of stubby lasers in the nose, controlled by the pilot.'),
  ('warrior-assault-hoversled-light', 1, 'Guraskov G-110 Laser Pulse Cannons (2)', '5D6 M.D. per single dual pulse blast, or 1D6x10 M.D. for a simultaneous dual burst from both guns at the same target', 1, '3,000 feet (914 m)', 'Each single or dual blast counts as one of the pilot''s melee attacks/actions', 'E-clip with 20 pulse blasts each, or 50 blasts each from a mini-generator (recharges one blast every two minutes); effectively unlimited if the sled is nuclear powered', NULL, 'Primary purpose assault/siege, secondary defense. Front-mounted in the armored nose; swivel 45 degrees up and down.'),
  ('warrior-assault-hoversled-light', 2, 'Manned AR-60 Rail Gun or Laser Gun', 'Rail Gun: 1D4x10+10 M.D. per burst of 10 shells (bursts only). Laser Gun: 3D6 M.D. per blast', 1, 'Rail gun 4,000 feet (1200 m); laser 2,000 feet (610 m)', 'Equal to the gunner''s attacks per melee; each blast or burst counts as one melee action', 'Rail Gun: belt-fed drum with 1,200 rounds (120 shots). Laser: 20 per G-Clip, or effectively unlimited if nuclear', NULL, 'Primary purpose anti-personnel, secondary defense. A sled carries one gun or the other, never both. Low swivel mount at the rear behind the passenger seat: the gunner is -1 to strike when twisting to fire it, or it can be fired from the forward HUD fire control at -3 to hit. The M.D.C. table calls this location ''Manned, Rear Laser (1)''.'),
  ('warrior-assault-hoversled-light', 3, 'Mini-Missile Launchers (3)', 'Varies with missile type (5D6, 1D4x10 or 1D6x10 M.D.; silver flechette does 3D6 M.D. to humans but 1D6x10 M.D. to vampires and supernatural beings vulnerable to silver; or smoke)', 1, 'One mile (1.6 km)', '1, 2 or 4 missiles in a volley', '18 total, six per launcher', NULL, 'Primary purpose anti-personnel, secondary support. Two launchers on the sides, one at the rear. An iris opens on the tube before firing: anyone who notices and understands it gets +2 to dodge/roll with impact. Destroying a launcher has a 01-20% chance of detonating all its missiles.'),
  ('warrior-assault-hoversled-light', 4, 'Raker Blades (2)', '4D6 M.D. per blade from a fly-by raking strike', 1, NULL, NULL, NULL, NULL, 'Primary purpose anti-personnel, secondary support. Giant vibro-blades, each 5 feet (1.5 m) long, that unfold under the sled for strafing runs. No range, rate of fire or payload printed.'),
  ('warrior-assault-hoversled-heavy', 1, 'Guraskov G-110 Laser Pulse Cannons (2)', '5D6 M.D. per single dual pulse blast, or 1D6x10 M.D. for a simultaneous dual burst from both guns at the same target', 1, '3,000 feet (914 m)', 'Each single or dual blast counts as one of the pilot''s melee attacks/actions', 'E-clip with 20 pulse blasts each, or 50 blasts each from a mini-generator (recharges one blast every two minutes); effectively unlimited if the sled is nuclear powered', NULL, 'Primary purpose assault/siege, secondary defense. Front-mounted in the armored nose; swivel 45 degrees up and down.'),
  ('warrior-assault-hoversled-heavy', 2, 'Manned AR-60 Rail Gun or Laser Gun', 'Rail Gun: 1D4x10+10 M.D. per burst of 10 shells (bursts only). Laser Gun: 3D6 M.D. per blast', 1, 'Rail gun 4,000 feet (1200 m); laser 2,000 feet (610 m)', 'Equal to the gunner''s attacks per melee; each blast or burst counts as one melee action', 'Rail Gun: belt-fed drum with 1,200 rounds (120 shots). Laser: 20 per G-Clip, or effectively unlimited if nuclear', NULL, 'Primary purpose anti-personnel, secondary defense. A sled carries one gun or the other, never both. Low swivel mount at the rear behind the passenger seat: the gunner is -1 to strike when twisting to fire it, or it can be fired from the forward HUD fire control at -3 to hit. The M.D.C. table calls this location ''Manned, Rear Laser (1)''.'),
  ('warrior-assault-hoversled-heavy', 3, 'Mini-Missile Launchers (3)', 'Varies with missile type (5D6, 1D4x10 or 1D6x10 M.D.; silver flechette does 3D6 M.D. to humans but 1D6x10 M.D. to vampires and supernatural beings vulnerable to silver; or smoke)', 1, 'One mile (1.6 km)', '1, 2 or 4 missiles in a volley', '18 total, six per launcher', NULL, 'Primary purpose anti-personnel, secondary support. Two launchers on the sides, one at the rear. An iris opens on the tube before firing: anyone who notices and understands it gets +2 to dodge/roll with impact. Destroying a launcher has a 01-20% chance of detonating all its missiles.'),
  ('warrior-assault-hoversled-heavy', 4, 'Raker Blades (2)', '4D6 M.D. per blade from a fly-by raking strike', 1, NULL, NULL, NULL, NULL, 'Primary purpose anti-personnel, secondary support. Giant vibro-blades, each 5 feet (1.5 m) long, that unfold under the sled for strafing runs. No range, rate of fire or payload printed.'),
  ('warlord-war-chariot', 1, 'Giant Wheels', '1D4x10 M.D. automatically to anyone caught beneath the wheels', 1, 'Impact', NULL, NULL, NULL, 'Primary purpose anti-personnel, secondary utility/ground clearing and field plowing. Each wheel is 8 feet (2.4 m) across and 4 feet (1.2 m) wide with 4 ft (1.2 m) blades across the tread.'),
  ('warlord-war-chariot', 2, 'Manned AR-210 Rail Guns (2)', '2D4x10 M.D. per 30 round burst, per rail gun', 1, '4,000 feet (1200 m)', 'Equal to the combined hand to hand attacks (usually 4-6) of each gunner', '3,000 rounds per gun (100 shots each)', NULL, 'Primary purpose anti-armor, secondary anti-personnel. Open-air swivel mounts on top of the cage, 360 degree rotation and a 50 degree arc of fire. Manned and fired separately; both cannot fire at the same target simultaneously. Weight 500 pounds (225 kg) each.'),
  ('warlord-war-chariot', 3, 'Flamethrower', '2D6 M.D. per single shot; 4D6 M.D. for a long spray (counts as a burst, uses two melee actions)', 1, '800 feet (244 m)', 'Equal to the combined hand to hand attacks (usually 4-6) of the gunner', '100 single shots or 50 long sprays/bursts', NULL, 'Primary purpose anti-personnel. Manned upright swivel mount atop the pilot''s compartment, 360 degree rotation and a 45 degree arc of fire. Each blast has a 01-70% chance of setting combustibles on fire. Weight 300 pounds (135 kg).'),
  ('warlord-war-chariot', 4, 'Short-Range Lasers (2)', '3D6 M.D. per single blast or 6D6 M.D. per simultaneous dual blast (counts as one melee attack)', 1, '1200 feet (610 km)', 'Equal to the pilot''s attacks per round', 'Effectively unlimited if nuclear; otherwise a generator pack with a 120 shot payload', NULL, 'Primary purpose anti-personnel, secondary defense. Forward mounted, 45 degree arc up and down, fired by button or Cyber-Link. The range is stored as printed; 1200 feet is 366 m, so the metric figure is a misprint.'),
  ('warlord-war-chariot', 5, 'Dual Buzz Saws (2)', '4D6 M.D. per cut of the blade', 1, NULL, NULL, NULL, NULL, 'Primary purpose anti-armor and barriers, secondary anti-personnel. Saws 4 ft (1.2 m) in diameter under the pilot''s compartment; they extend forward about four feet (1.2 m) and can be set from two feet (0.6 m) to about five feet (1.5 m) above ground. No range, rate of fire or payload printed.'),
  ('war-wagon-mechanized-ram', 1, 'Ion Turret Banks (20 total)', '3D6 M.D. per individual blast, 6D6 M.D. per twin blast', 1, '1,200 feet (366 m)', 'Two at a time or the full bank of ten, equal to the gunner''s number of attacks (typically 4-8)', 'Effectively unlimited if nuclear; 100 per turret on a multi-generator pack (liquid fuel vehicles)', NULL, 'Primary purpose barrage and anti-fortifications, secondary anti-personnel. Ten turrets per side, each bank with its own gunner; turrets tilt 45 degrees up and down and turn 90 degrees left and right, and cannot point forward. From a broadside no more than two blasts hit a human-sized target up to 8 feet (2.4 m) tall; 1D4 hit a small fast vehicle or fast Heavy Machine; 1D4+2 hit something the size of a sedan; 1D4+6 hit a building, bunker, cargo truck or ship. The ten-turret broadside is only effective against large, ideally stationary targets.'),
  ('war-wagon-mechanized-ram', 2, 'Manned Rail Gun Turrets (2)', '1D4x10 M.D. per 10 shell burst', 1, '4,000 feet (1,200 m)', NULL, '2,000 rounds (200 shots) each', NULL, 'Primary purpose defense, secondary anti-personnel. On top toward the front sides, reached by a hatch from inside; they cover troops entering and leaving. No rate of fire printed.'),
  ('war-wagon-mechanized-ram', 3, 'GU-SO Series Support Laser Cannon Turrets (2)', '6D6 per blast, per cannon, or 1D6x10+10 from simultaneous blasts from both', 1, '4,500 feet (1,371 m)', 'Equal to the combined hand to hand attacks (usually 4-6) of the operator', 'Effectively unlimited if nuclear; 200 per cannon on a multi-generator pack (liquid fuel vehicles)', NULL, 'Primary purpose assault/support. Mid-hull turrets with 360 degree rotation and a 90 degree arc of fire. The series name is stored as the page renders it, ''GU-SO''; it may be a scan of ''GU-50''.'),
  ('war-wagon-mechanized-ram', 4, 'Mini-Missile Turrets (2)', 'Varies with missile type', 1, 'About one mile (1.6 km)', '1, 2 or 4 missiles in a volley', '80 total; 40 per launcher', NULL, 'Primary purpose anti-vehicle, secondary support. Top-mounted launchers that rotate in any direction. Blast radius varies.'),
  ('war-wagon-mechanized-ram', 5, 'Medium-Range Missile Launcher (1)', 'Varies with missile', 1, 'About 20 miles average (32 km)', '1, 2 or 4 missiles in a volley', '24', NULL, 'Primary purpose anti-vehicle, secondary support. Mounted at the back above the rear exit hatch. Blast radius varies.'),
  ('war-wagon-mechanized-ram', 6, 'Hydraulic Ram System', '2D4x10 M.D. +20 M.D. per 20 mph of speed', 1, NULL, 'One; uses up 10 to 15 seconds and all but one of the pilot''s attacks for that melee round', NULL, NULL, 'Primary purpose siege, secondary anti-vehicle. The V-shaped ram runs a quarter of the vehicle''s length and punches forward at the moment of collision. The War Wagon itself takes 1D4x10 M.D. to the ram. A claxon and countdown warn the troop compartment; ordinary humans not harnessed in, even in body armor, take 2D6 M.D. from the impact.'),
  ('warthrone', 1, 'Concealed Forward Lasers (4)', 'A single blast does 3D6 M.D., two 6D6 M.D., three 1D4x10+10 M.D., and all four 1D6x10+10 M.D.', 1, '1,200 feet (366 m)', 'Once per Combat Round (15 seconds)', 'Effectively unlimited', NULL, 'Primary purpose defense. Hidden behind sliding panels at the front of the disk and fixed forward, so the whole platform must rise, drop or tilt to aim. Controlled by the pilot or the Warlord.'),
  ('warthrone', 2, 'Concealed Underbelly Lasers (10)', '2D6 M.D. per individual blast, 4D6 M.D. per twin blast', 1, '500 feet (152 m)', 'Four showers of laser blasts per melee round (automated and on a timer)', 'Effectively unlimited', NULL, 'Primary purpose barrage and anti-personnel, secondary defense. Fire straight down in a random sequence or all at a 10-40% degree angle, as printed. No more than one blast hits a human-sized target up to 8 feet (2.4 m) tall or a small vehicle such as a hovercycle; 1D4 blasts hit a horse-sized animal, sedan or small truck; 1D4+2 hit a semi-truck, tank or APC. Only effective against large crowds and large targets; a group of 1-5 human-sized people is +1 to dodge. Cannot point directly forward or backward.'),
  ('warthrone', 3, 'Multi-Weapon Arms (2): High-Powered Precision Laser', '4D6 M.D. per blast, per arm', 1, '3,000 feet (914 m)', NULL, 'Effectively unlimited', '+1 to strike', 'Primary purpose defense, secondary anti-personnel. One of the weapons in each of the two gunner-controlled arms stowed under the disk; each arm rotates 360 degrees with a 170 degree arc of fire. The two arms cannot fire at the same target together unless it is very large and slow or stationary. No rate of fire printed.'),
  ('warthrone', 4, 'Multi-Weapon Arms (2): Twin-Barrel Rail Gun', '1D4x10 M.D. per 10 round burst', 1, '4,000 feet (1,200 m)', NULL, '2,000 rounds (200 shots) each', NULL, 'Primary purpose defense, secondary anti-personnel. One of the weapons in each of the two gunner-controlled arms stowed under the disk; each arm rotates 360 degrees with a 170 degree arc of fire. The two arms cannot fire at the same target together unless it is very large and slow or stationary. No rate of fire printed.'),
  ('warthrone', 5, 'Multi-Weapon Arms (2): Electro-Blast', '3D6 M.D. to a 10 foot (3 m) diameter', 1, '120 feet (36.6 m)', NULL, 'Effectively unlimited', NULL, 'Primary purpose defense, secondary anti-personnel. One of the weapons in each of the two gunner-controlled arms stowed under the disk; each arm rotates 360 degrees with a 170 degree arc of fire. The two arms cannot fire at the same target together unless it is very large and slow or stationary. No rate of fire printed. The discharge hits everything in the 10 ft/3 m area.'),
  ('warthrone', 6, 'Multi-Weapon Arms (2): Physical Punch/Strike', '1D6 M.D.', 1, '12 feet (3.6 m)', NULL, NULL, NULL, 'Primary purpose defense, secondary anti-personnel. One of the weapons in each of the two gunner-controlled arms stowed under the disk; each arm rotates 360 degrees with a 170 degree arc of fire. The two arms cannot fire at the same target together unless it is very large and slow or stationary. No rate of fire printed. The arm swats nearby enemies with the side of the weapon housing or barrels.'),
  ('warthrone', 7, 'Mini-Missile Launchers (2)', 'Varies with missile type', 1, 'About one mile (1.6 km)', '1, 2 or 4 missiles in a volley', '64 total; 32 per launcher', NULL, 'Primary purpose assault, secondary anti-personnel. The pair fold out of a concealed compartment on deck. Blast radius varies.'),
  ('warthrone', 8, 'Medium-Range Missile Launcher (1)', 'Varies with missile type', 1, 'About 20 miles average (32 km)', '1, 2 or 4 missiles in a volley', 'Eight', NULL, 'Primary purpose anti-vehicle, secondary support. A large forward nose/underbelly launcher. Blast radius varies with missile type.'),
  ('wingrider-flying-wing', 1, 'Chulki Hooks (4; two on each wing)', 'Hook and carry: a dragged victim takes 1D6 M.D. per melee round, or 4D6 M.D. +6 M.D. per 50 mph/80 km of speed when slammed into something big (half if only dropped from a great height). Detached grapnel fired as a projectile: 1D4 M.D. Wing Clip: 1D6 M.D. per 50 mph (80 km). Body Skip/Clip: 1D6 M.D. per 50 mph (80 km). Body Slam: 2D6 M.D. per 50 mph (80 km)', 1, 'Touch or clip; the detached grapnel projectile has about 400 feet (122 m)', 'Once each Combat Round (15 seconds)', 'N/A', NULL, 'Primary purpose assault, secondary maneuvering. Grapnel launchers under the wings about 4 feet (1.2 m) from the tips. Hooking a target counts as two melee attacks and the victim loses two attacks and initiative; while carried or dragged the victim loses half his attacks and initiative, shoots wild, is -6 to strike, parry and dodge and -50% on skills; a slam knocks the victim off the hook 01-90% of the time. Light and Heavy Machine ''Borgs are only pulled off their feet (lose two melee actions and initiative). Auto-release by button or after 60 seconds (four melee rounds). A grapnel anchored to a pole, tree or giant robot allows a sling-shot turn losing no more than 5% speed; onlookers lose one melee attack/action. Wing Clip needs a control roll at -20% piloting; on a failure roll percentile: 01-33 crash (vehicle 2D6x10 M.D., pilot 6D6 M.D., stunned one melee round, three melee actions to restart); 34-66 clips ground or trees (no attacks for two melee rounds, vehicle 5D6 M.D., pilot 1D6 M.D.); 67-00 brief spin (loses 1D4+2 melee actions). Body Slam does 1D4 M.D. per 50 mph (80 km) to the Wing''s own main body and halves its speed for one melee round.'),
  ('wingrider-flying-wing', 2, 'Strafing Lasers (2)', 'A single blast does 2D6 M.D.; simultaneous twin blasts do 4D6 M.D. (counts as one melee attack)', 1, '1,200 feet (366 m)', 'Equal to the pilot''s hand to hand attacks', 'Effectively unlimited, or 100 each for liquid fuel models', NULL, 'Primary purpose defense. Small short-range lasers above the shoulders on either side of the pilot.'),
  ('wingrider-flying-wing', 3, 'Mini-Missile Launcher', 'Varies with missile type', 1, '8 miles (12.8 km)', '1 or 2 missiles', '12 mini-missiles in the main system', NULL, 'Primary purpose assault, secondary sabotage. Center forward section, fired by button. The 8 mile range is as printed, although the book''s other mini-missile launchers print about one mile.'),
  ('wingrider-flying-wing', 4, 'Wing Tip Missiles', 'Varies with missile type', 1, NULL, NULL, 'Four additional mini-missiles (two on each wing tip), or two short-range or medium-range missiles (one on each wing tip)', NULL, 'Optional. Attached to the wing tips as an addition to the main mini-missile system; printed inside that weapon''s payload line.'),
  ('wingrider-power-armor', 1, 'Retractable Vibro-Sword', '2D6 M.D.', 1, NULL, NULL, NULL, NULL, 'Built into one arm.'),
  ('wingrider-power-armor', 2, 'Vibro-Claws', '2D4 M.D.', 1, NULL, NULL, NULL, NULL, 'On the other arm, extending from the top of the hand to beyond the fingers.'),
  ('wingrider-power-armor', 3, 'Forearm Laser', '2D6 M.D.', 1, '1000 ft/305 m', NULL, NULL, NULL, 'A small laser on the same arm as the vibro-claws. No rate of fire or payload printed.'),
  ('mm-61-explorer-exoframe', 1, 'Underarm Tool: Plasma Torch/Flamethrower', '2D6 M.D.', 1, '50 foot/15 m', NULL, 'Powered by an E-Pack, or nuclear', NULL, 'One of three choices for the single modular tool mount under the hydraulic arm. No rate of fire printed.'),
  ('mm-61-explorer-exoframe', 2, 'Underarm Tool: High-Powered Laser', '3D6 M.D.', 1, '2000 foot/610 m', NULL, 'Powered by an E-Pack, or nuclear', NULL, 'One of three choices for the single modular tool mount under the hydraulic arm. No rate of fire printed.'),
  ('mm-61-explorer-exoframe', 3, 'Underarm Tool: Extendible Heavy Drill', '5D6 S.D.C., 1D6x10 S.D.C., 2D4x10 S.D.C., One M.D., 1D4 M.D. or 1D6 M.D.', 1, NULL, NULL, 'Powered by an E-Pack, or nuclear', NULL, 'One of three choices for the single modular tool mount under the hydraulic arm. Extends two feet beyond the hand when the hand is retracted. Settings run from S.D.C. to Mega-Damage.'),
  ('mm-61-explorer-exoframe', 4, 'Concealed Forearm Laser', 'Adjustable: One M.D., 1D6 M.D., 2D6 M.D. or 3D6 M.D.', 1, '1200 foot/366 m', NULL, 'Powered by an E-Pack, or nuclear', NULL, 'In the forearm of the non-extending arm. Intended as a tool for cutting and welding metal and stone and for excavation. No rate of fire printed.'),
  ('mm-61-explorer-exoframe', 5, 'Forearm Mini-Missiles', 'Not printed', 1, NULL, NULL, 'Three mini-missiles can be mounted on each forearm', NULL, 'Optional. The block prints only the mounting capacity; no damage, range or rate of fire.');

-- Read the result back. This script asserts its OWN rows and nothing else.
SELECT 'all 18 Warlords of Russia vehicles and power armors are in' AS assertion, count(*) AS got, 18 AS want
  FROM vehicles WHERE slug IN ('novyet-arctic-hoverbike', 'novyet-snow-jetsled', 'novyet-landcrawler-sku', 'novyet-explorer-sku', 'novyet-bear-atv', 'heavy-mdc-snowmobile', 'tek-12-yy110-bushbike', 'tek-20-yy210-borgbike', 'landflier', 'warrior-assault-hoversled-light', 'warrior-assault-hoversled-heavy', 'warlord-war-chariot', 'war-wagon-mechanized-ram', 'warthrone', 'wingrider-flying-wing', 'wingrider-power-armor', 'war-knight-power-armor', 'mm-61-explorer-exoframe') AND source_book LIKE 'Rifts World Book 17: Warlords of Russia p.%';
SELECT 'their 152 M.D.C. locations are in' AS assertion, count(*) AS got, 152 AS want
  FROM vehicle_locations WHERE vehicle_slug IN ('novyet-arctic-hoverbike', 'novyet-snow-jetsled', 'novyet-landcrawler-sku', 'novyet-explorer-sku', 'novyet-bear-atv', 'heavy-mdc-snowmobile', 'tek-12-yy110-bushbike', 'tek-20-yy210-borgbike', 'landflier', 'warrior-assault-hoversled-light', 'warrior-assault-hoversled-heavy', 'warlord-war-chariot', 'war-wagon-mechanized-ram', 'warthrone', 'wingrider-flying-wing', 'wingrider-power-armor', 'war-knight-power-armor', 'mm-61-explorer-exoframe');
SELECT 'their 47 weapon entries are in' AS assertion, count(*) AS got, 47 AS want
  FROM vehicle_weapons WHERE vehicle_slug IN ('novyet-arctic-hoverbike', 'novyet-snow-jetsled', 'novyet-landcrawler-sku', 'novyet-explorer-sku', 'novyet-bear-atv', 'heavy-mdc-snowmobile', 'tek-12-yy110-bushbike', 'tek-20-yy210-borgbike', 'landflier', 'warrior-assault-hoversled-light', 'warrior-assault-hoversled-heavy', 'warlord-war-chariot', 'war-wagon-mechanized-ram', 'warthrone', 'wingrider-flying-wing', 'wingrider-power-armor', 'war-knight-power-armor', 'mm-61-explorer-exoframe');

-- Records this run. See db/migrations/024-data-script-runs.sql.
INSERT INTO data_script_runs (filename) VALUES ('add-warlords-of-russia-vehicles.sql');
